export type ItemOption = {
    id: string;
    color: string | null;
    icon: string | null;
    itemScore?: {
        score: string | number;
    };
    parentId: string;
    sortOrder: number | null;
    value: string;
};
export type ItemOptionUpdate = {
    id: string;
    color: string | null;
    icon: string | null;
    value: string;
};
export type ItemOptionSet = {
    id: string;
    itemOptions: ItemOption[];
};
